const list = flow.get("list") || []

if (list.length === 0) {
    return null
}

let index = flow.get("currentIndex") || 0

index += msg.payload

if (index < 0) {
    index = list.length - 1
}

if (index >= list.length) {
    index = 0
}

flow.set("currentIndex", index)

msg.payload = list[index].value

return msg

const list = flow.get("list") || []

const index = list.findIndex(
    item => item.value === msg.payload
)

if (index >= 0) {
    flow.set("currentIndex", index)
}

return msg
